  return new Promise((resolve, reject) => {
    if (firstRequest === true) {
      firstRequest = false;
      setTimeout(() => {
        firstRequest = true;
        resolve(newName);
        // 매번 다른 요청이 더 느리게 반환되도록 시뮬레이션합니다.
